430: /**
431:  * v1.5.14: ZB ESAMU PIGIU PREKIU UPDATE BLOKAVIMAS (tik ZB Import #2,#3).
432:  *
433:  * Hook: wp_all_import_is_post_to_update.
434:  *
435:  * ESAMA preke, kuri < PETSHOP_XML_ZB_MIN_COST IR NE konservas -> BLOKUOTI update.
436:  * Priezastis: tokia preke neturi buti kataloge (kartele), bet jei ja LEIDZIAM
437:  * update'inti, importas perkrauna nuotrauka (ShortPixel kreditai) ir gali mesti
438:  * i trash -> cron ciklas. Blokuojant update preke NELIECIAMA -> nuotrauka
439:  * neperkraunama. Vienkartinis valymas (snippet) ja istrina VISAM; po to cron
440:  * bando kurti -> block_zb_create blokuoja PRIES nuotrauka.
441:  *
442:  * Fail-safe = LEISTI: jei _zb_cost tuscias/0 (nezinom savikainos) arba preke
443:  * konservas -> NEBLOKUOJAM (status quo). Tik gryni atvejai blokuojami.
444:  *
445:  * Pastaba: sis filtras eina PO block_legacy_update (prioritetas 9 vs 10),
446:  * tad Legacy prekes jau atfiltruotos anksciau (ju neliecia).
447:  */
448: add_filter( 'wp_all_import_is_post_to_update', 'petshop_xml_block_zb_cheap_update', 11, 4 );
449: 
450: function petshop_xml_block_zb_cheap_update( $continue_import, $post_id, $data, $import_id ) {
451: 
452:     if ( get_post_type( $post_id ) !== 'product' ) {
453:         return $continue_import;
454:     }
455: 
456:     // Tik ZB importai (#2 initial, #3 stock)
457:     if ( ! in_array( (int) $import_id, PETSHOP_XML_ZB_ALL_IMPORT_IDS, true ) ) {
458:         return $continue_import;
459:     }
460: 
461:     // Legacy prekes — jau blokuotos block_legacy_update (prioritetas 9). Saugiklis.
462:     if ( petshop_xml_is_legacy_product( $post_id ) ) {
463:         return $continue_import;
464:     }
465: 
466:     // Manual override — neliesti
467:     if ( get_post_meta( $post_id, '_manual_price_override', true ) === 'yes' ) {
468:         return $continue_import;
469:     }
470: 
471:     $zb_cost = (float) get_post_meta( $post_id, '_zb_cost', true );
472: 
473:     // Fail-safe: jei savikainos nezinom -> leisti (neblokuojam aklai)
474:     if ( $zb_cost <= 0 ) {
475:         return $continue_import;
476:     }
477: 
478:     // Konservas -> NEBLOKUOJAM (konservai leidziami net pigus, box rinkiniai)
479:     if ( petshop_xml_is_konservas( $post_id ) ) {
480:         return $continue_import;
481:     }
482: 
483:     // Pigi (< kartele) IR ne konservas IR esama -> BLOKUOTI update
484:     if ( $zb_cost < PETSHOP_XML_ZB_MIN_COST ) {
485:         petshop_xml_log_structured( [
486:             'action'    => 'ZB-BLOCK-CHEAP-UPDATE',
487:             'post_id'   => $post_id,
488:             'sku'       => (string) get_post_meta( $post_id, '_sku', true ),
489:             'zb_cost'   => $zb_cost,
490:             'import_id' => $import_id,
491:             'note'      => 'ZB update prevented for existing cheap non-konservas (no image reload, v1.5.14)',
492:         ] );
493:         return false;
494:     }
495: 
496:     return $continue_import;
497: }
